public class CountdownPrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected [" + expected + "] but got [" + actual + "]");
            failures++;
        }
    }

    static String capture(int n) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            CountdownPrinter.countdown(n);
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("countdown(3)", "3\n2\n1\nliftoff\n", capture(3));
        check("countdown(1)", "1\nliftoff\n", capture(1));
        check("countdown(0) goes straight to liftoff", "liftoff\n", capture(0));
        check("countdown(5)", "5\n4\n3\n2\n1\nliftoff\n", capture(5));
        check("countdown(2)", "2\n1\nliftoff\n", capture(2));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

